/// Raven `SpotWouldTelefrag` — would a client spawn on `spot` overlap another
/// client?
///
/// Source: `oracle/oracle/codemp/game/g_client.c:532-552`
pub fn SpotWouldTelefrag(ctx: GameContext<'_>, spot: *mut gentity_t) -> qboolean {
    unsafe {
        let mut touch: [c_int; MAX_GENTITIES] = [0; MAX_GENTITIES];
        let mut mins: vec3_t = [0.0; 3];
        let mut maxs: vec3_t = [0.0; 3];

        for k in 0..3 {
            mins[k] = (*spot).s.origin[k] + playerMins[k];
            maxs[k] = (*spot).s.origin[k] + playerMaxs[k];
        }
        let num = trap::EntitiesInBox(
            ctx.engine,
            GEntitiesInBoxArgs::new(
                &mins as *const vec3_t,
                &maxs as *const vec3_t,
                touch.as_mut_ptr(),
                MAX_GENTITIES as c_int,
            ),
        );

        let mut i = 0;
        while i < num {
            let hit = &mut (*ctx.world).entities[touch[i as usize] as usize] as *mut gentity_t;
            // if ( hit->client && hit->client->ps.stats[STAT_HEALTH] > 0 ) — the
            // health test is commented out in Raven; any client presence telefrags.
            if !(*hit).client.is_null() {
                return qtrue;
            }
            i += 1;
        }

        qfalse
    }
}

/// Raven `SpotWouldTelefrag2` — would `mover` moved to `dest` overlap a solid?
///
/// Source: `oracle/oracle/codemp/game/g_client.c:554-580`
pub fn SpotWouldTelefrag2(ctx: GameContext<'_>, mover: *mut gentity_t, dest: vec3_t) -> qboolean {
    unsafe {
        let mut touch: [c_int; MAX_GENTITIES] = [0; MAX_GENTITIES];
        let mut mins: vec3_t = [0.0; 3];
        let mut maxs: vec3_t = [0.0; 3];

        for k in 0..3 {
            mins[k] = dest[k] + (*mover).r.mins[k];
            maxs[k] = dest[k] + (*mover).r.maxs[k];
        }
        let num = trap::EntitiesInBox(
            ctx.engine,
            GEntitiesInBoxArgs::new(
                &mins as *const vec3_t,
                &maxs as *const vec3_t,
                touch.as_mut_ptr(),
                MAX_GENTITIES as c_int,
            ),
        );

        let mut i = 0;
        while i < num {
            let hit = &mut (*ctx.world).entities[touch[i as usize] as usize] as *mut gentity_t;
            if hit == mover {
                i += 1;
                continue;
            }
            if (*hit).r.contents & (*mover).r.contents != 0 {
                return qtrue;
            }
            i += 1;
        }

        qfalse
    }
}

/// Raven `SelectNearestDeathmatchSpawnPoint` — find the spot we DON'T want.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:590-611`
pub fn SelectNearestDeathmatchSpawnPoint(from: vec3_t) -> *mut gentity_t {
    unsafe {
        let mut nearestDist: f32 = 999999.0;
        let mut nearestSpot: *mut gentity_t = core::ptr::null_mut();
        let mut spot: *mut gentity_t = core::ptr::null_mut();

        loop {
            spot = crate::g_utils::G_Find(
                spot,
                fofs_classname(),
                b"info_player_deathmatch\0".as_ptr() as *const c_char,
            );
            if spot.is_null() {
                break;
            }
            let mut delta: vec3_t = [0.0; 3];
            for k in 0..3 {
                delta[k] = (*spot).s.origin[k] - from[k];
            }
            let dist = VectorLength(delta);
            if dist < nearestDist {
                nearestDist = dist;
                nearestSpot = spot;
            }
        }

        nearestSpot
    }
}

/// Raven `SelectRandomDeathmatchSpawnPoint` — a random non-telefragging spot.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:622-645`
pub fn SelectRandomDeathmatchSpawnPoint(ctx: GameContext<'_>) -> *mut gentity_t {
    const MAX_SPAWN_POINTS: usize = 128;
    unsafe {
        let mut count: c_int = 0;
        let mut spot: *mut gentity_t = core::ptr::null_mut();
        let mut spots: [*mut gentity_t; MAX_SPAWN_POINTS] = [core::ptr::null_mut(); MAX_SPAWN_POINTS];

        loop {
            spot = crate::g_utils::G_Find(
                spot,
                fofs_classname(),
                b"info_player_deathmatch\0".as_ptr() as *const c_char,
            );
            if spot.is_null() {
                break;
            }
            if SpotWouldTelefrag(ctx, spot) != 0 {
                continue;
            }
            spots[count as usize] = spot;
            count += 1;
        }

        if count == 0 {
            // no spots that won't telefrag
            return crate::g_utils::G_Find(
                core::ptr::null_mut(),
                fofs_classname(),
                b"info_player_deathmatch\0".as_ptr() as *const c_char,
            );
        }

        let selection = crate::bg_lib::rand() % count;
        spots[selection as usize]
    }
}

