/// Raven `SetClientViewAngle` — set the client's view + delta angles.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1116-1128`
pub fn SetClientViewAngle(ent: *mut gentity_t, angle: vec3_t) {
    unsafe {
        let client = (*ent).client;
        // set the delta angle
        for i in 0..3 {
            // ANGLE2SHORT(x) == ((int)((x)*65536/360) & 65535)
            let cmdAngle: c_int = ((angle[i] * 65536.0 / 360.0) as c_int) & 65535;
            (*client).ps.delta_angles[i] = cmdAngle - (*client).pers.cmd.angles[i] as c_int;
        }
        // VectorCopy( angle, ent->s.angles );
        (*ent).s.angles = angle;
        // VectorCopy( ent->s.angles, ent->client->ps.viewangles );
        (*client).ps.viewangles = (*ent).s.angles;
    }
}

